  (* [comment removed for export] *)
  Lemma nodup_remove : forall L x, List.NoDup (map blk_id L) -> In x L -> List.NoDup (map blk_id (as_lb_remove H (blk_id x) L)).
  Proof.
    intros L x ND IN. pose proof (lb_remove_perm H HH _ _ ND IN) as P1. pose proof (NoDup_ids_perm _ _ P1 ND) as ND1.
    cbn in ND1. inversion ND1; subst; assumption.
  Qed.

  Lemma in_remove : forall L b x, List.NoDup (map blk_id L) -> In x L -> In b L -> blk_id b <> blk_id x -> In b (as_lb_remove H (blk_id x) L).
  Proof. intros L b x ND INx IN NE. apply (ah_lb_remove_keep H HH); [exact ND| exact IN| exact NE]. Qed.

  Lemma remove_sub : forall L p b, In b (as_lb_remove H p L) -> In b L.
  Proof. intros L p b IN. exact (proj2 (proj2 (ah_lb_remove H HH)) _ _ _ IN). Qed.

  (* [comment removed for export] *)
  Lemma blkX_off : forall s L m p b n p' b' n', as_RHEAP H s L m -> In (p, b, n) L -> In (p', b', n') L -> p <> p' -> 0 <= n -> 0 <= n' ->
    Forall (fun iv : Z * Z => b + n <= fst iv \/ snd iv <= b) (blkX b' n') /\ Forall (fun iv : Z * Z => sh b + nsh n <= fst iv \/ snd iv <= sh b) (blkX b' n').
  Proof.
    intros s L m p b n p' b' n' RH IN IN' NE Hn Hn'.
    pose proof (ah_blocks H HH _ _ _ _ RH IN) as (X1 & _ & X3 & _ & _ & _ & X7). cbn [blk_addr blk_size fst snd] in X1, X3, X7. pose proof (aapp_bounds _ _ X7 X3) as (_ & _ & X8 & _).
    pose proof (ah_blocks H HH _ _ _ _ RH IN') as (Y1 & _ & Y3 & _ & _ & _ & Y7). cbn [blk_addr blk_size fst snd] in Y1, Y3, Y7. pose proof (aapp_bounds _ _ Y7 Y3) as (_ & _ & Y8 & _).
    pose proof (blocks_neq_disjoint H HH _ _ _ _ _ RH IN IN' ltac:(intros E; injection E; intros; subst; exact (NE eq_refl))) as D1.
    pose proof (blocks_sh_disjoint H HH _ _ _ _ _ RH IN IN' ltac:(cbn; exact NE)) as T1. cbn [blk_addr blk_size fst snd] in D1, T1.
    pose proof (aapp_disjoint_sh b' n' b n Y7 (Z.lt_le_incl _ _ X1) (Z.lt_le_incl _ _ X8) Hn) as U1.
    pose proof (aapp_disjoint_sh b n b' n' X7 (Z.lt_le_incl _ _ Y1) (Z.lt_le_incl _ _ Y8) Hn') as U1'.
    unfold blkX. split; (repeat apply Forall_cons; [| | apply Forall_nil]); cbn [fst snd]; [clear - D1; lia| clear - U1'; lia| clear - U1; lia| clear - T1; lia].
  Qed.

  (* [comment removed for export] *)
  Lemma blkX_bounds : forall s L m p b n, as_RHEAP H s L m -> In (p, b, n) L ->
    Forall (fun iv : Z * Z => AIMG_TOP <= fst iv /\ snd iv <= aceil) (blkX b n).
  Proof.
    intros s L m p b n RH IN. pose proof (ah_blocks H HH _ _ _ _ RH IN) as (X1 & _ & X3 & X4 & X5 & _ & X7). cbn [blk_addr blk_size fst snd] in X1, X3, X4, X5, X7.
    pose proof (aapp_bounds _ _ X7 X3) as (_ & _ & X8 & _). pose proof aceil_facts as (AF1 & _).
    pose proof (sh_nsh_high b n (Z.lt_le_incl _ _ X1) X3 (Z.lt_le_incl _ _ X8)) as W9. pose proof (sh_mono 0 b (Z.lt_le_incl _ _ X1)) as M0. change (sh 0) with 2147450880 in M0.
    unfold blkX. repeat apply Forall_cons; [| | apply Forall_nil]; cbn [fst snd]; unfold AIMG_TOP, AHI_LO in *; [clear - X4 X5; lia| clear - W9 M0 AF1; lia].
  Qed.
