  (* [comment removed for export] *)
  Lemma rin_ivs_incl : forall X X' a, (forall iv, In iv X -> In iv X') -> rin_ivs X a -> rin_ivs X' a.
  Proof.
    induction X as [|[l h] X IH]; intros X' a SUB K; cbn in K; [destruct K|].
    destruct K as [K|K]; [eapply rin_ivs_In; [apply SUB; left; reflexivity| exact K]| apply (IH X' a); [intros iv Hiv; apply SUB; right; exact Hiv| exact K]].
  Qed.
  (* [comment removed for export] *)
  Ltac rin_incl K := eapply rin_ivs_incl; [| exact K]; intros iv Hiv; unfold blkX, fr1_XS in Hiv |- *; cbn [app] in Hiv |- *; repeat (destruct Hiv as [<-|Hiv]; [cbn; tauto|]); destruct Hiv.
  (* [comment removed for export] *)

  Lemma errno_off_lo : forall W, Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) W -> disjoint_from W AERRNO 4.
  Proof.
    induction W as [|[l h] W IH]; intros FW; cbn; [exact I|]. split; [| apply IH; exact (Forall_inv_tail FW)].
    pose proof (Forall_inv FW) as K. cbn in K. rewrite AERRNO_val. unfold AIMG_TOP in K. lia.
  Qed.

